      "reading": "11.1959",
      "interpretation": "Banda inferior — referência de sobrevenda/apoio dinâmico em correções profundas."
    },
    {
      "indicator": "BB_mid",
      "reading": "11.7965",
      "interpretation": "Média das Bollinger coincide com MM20 — suporte dinâmico de curto prazo."
    },
    {
      "indicator": "BB_upper",
      "reading": "12.3971",
